impl<E: EthSpec> KzgVerifiedDataColumn<E> {
    pub fn new(
        data_column: Arc<DataColumnSidecar<E>>,
        kzg: &Kzg,
    ) -> Result<Self, (Option<ColumnIndex>, KzgError)> {
        verify_kzg_for_data_column(data_column, kzg)
